namespace APX.Domain.Admin;
public enum AdminUserStatus { Active, Disabled, Archived }
public sealed class AdminUser { public Guid Id { get; set; } public string? Email { get; set; } public string? Phone { get; set; } public string DisplayName { get; set; } = string.Empty; public AdminUserStatus Status { get; set; } = AdminUserStatus.Active; public DateTimeOffset? LastLoginAt { get; set; } public DateTimeOffset CreatedAt { get; set; } public DateTimeOffset UpdatedAt { get; set; } public ICollection<AdminUserRole> UserRoles { get; } = new List<AdminUserRole>(); public ICollection<AuditEntry> AuditEntries { get; } = new List<AuditEntry>(); }
public sealed class Role { public Guid Id { get; set; } public string Name { get; set; } = string.Empty; public ICollection<AdminUserRole> UserRoles { get; } = new List<AdminUserRole>(); }
public sealed class AdminUserRole { public Guid AdminUserId { get; set; } public AdminUser AdminUser { get; set; } = null!; public Guid RoleId { get; set; } public Role Role { get; set; } = null!; }
public sealed class AuditEntry { public Guid Id { get; set; } public Guid? AdminUserId { get; set; } public AdminUser? AdminUser { get; set; } public string EntityType { get; set; } = string.Empty; public Guid EntityId { get; set; } public string Action { get; set; } = string.Empty; public string? BeforeJson { get; set; } public string? AfterJson { get; set; } public DateTimeOffset CreatedAt { get; set; } public string? IpAddress { get; set; } }
